-- start  table dump : institutions
CREATE TABLE IF NOT EXISTS `institutions` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Primary id for this table. This uniquely identifies the row.',
  `code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'If there is a defined ISO code for the institute this should be used here.',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'The institute name.',
  `acronym` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'If there is an acronym for the institute.',
  `country_id` int DEFAULT NULL COMMENT 'Foreign key to countries.id.',
  `contact` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'The contact at the institute which should be used for correspondence.',
  `phone` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'The telephone number for the institute.',
  `email` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'The email address to contact the institute.',
  `address` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT 'The postal address of the institute.',
  `created_on` datetime DEFAULT CURRENT_TIMESTAMP COMMENT 'When the record was created.',
  `updated_on` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'When the record was updated. This may be different from the created on date if subsequent changes have been made to the underlying record.',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `country_id` (`country_id`) USING BTREE,
  CONSTRAINT `institutions_ibfk_1` FOREIGN KEY (`country_id`) REFERENCES `countries` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Defines institutions within Germinate. Accessions may be associated with an institute and this can be defined here.';

-- end  table dump : institutions
