CREATE TABLE IF NOT EXISTS `mapdefinitions` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Primary id for this table. This uniquely identifies the row.',
  `mapfeaturetype_id` int NOT NULL COMMENT 'Foreign key to mapfeaturetypes (mapfeaturetypes.id).',
  `marker_id` int NOT NULL COMMENT 'Foreign key to markers (markers.id).',
  `map_id` int NOT NULL COMMENT 'Foreign key to maps (maps.id).',
  `definition_start` double(64,10) NOT NULL COMMENT 'Used if the markers location spans over an area more than a single point on the maps. Determines the marker start location.',
  `definition_end` double(64,10) DEFAULT NULL COMMENT 'Used if the markers location spans over an area more than a single point on the maps. Determines the marker end location.',
  `chromosome` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'The chromosome/linkage group that this marker is found on.',
  `arm_impute` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'If a chromosome arm is available then this can be entered here.',
  `created_on` datetime DEFAULT CURRENT_TIMESTAMP COMMENT 'When the record was created.',
  `updated_on` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'When the record was updated. This may be different from the created on date if subsequent changes have been made to the underlying record.',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `mapfeaturetype_id` (`mapfeaturetype_id`) USING BTREE,
  KEY `marker_id` (`marker_id`) USING BTREE,
  KEY `map_id` (`map_id`) USING BTREE,
  KEY `marker_id_2` (`marker_id`,`map_id`) USING BTREE,
  CONSTRAINT `mapdefinitions_ibfk_1` FOREIGN KEY (`mapfeaturetype_id`) REFERENCES `mapfeaturetypes` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `mapdefinitions_ibfk_2` FOREIGN KEY (`marker_id`) REFERENCES `markers` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `mapdefinitions_ibfk_3` FOREIGN KEY (`map_id`) REFERENCES `maps` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Relates genetic markers to a map and assigns a position (if known). Maps are made up of lists of markers and positions (genetic or physiscal and chromosome/linkage group assignation). In the case of QTL the definition_start and definition_end columns can be used to specify a range across a linkage group.';

