  `pedigreedescription_id` int NOT NULL COMMENT 'Foreign key pedigreedescriptions (pedigreedescriptions.id).',
  `relationship_description` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT 'Can be used as a meta-data field to describe the relationships if a complex rellationship is required. Examples may include, ''is a complex cross containing'', ''F4 generation'' and so on. This is used by the Helium pedigree visualiztion tool.',
  `created_on` datetime DEFAULT CURRENT_TIMESTAMP COMMENT 'When the record was created.',
